package app.asechka.android;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;import java.io.*;import java.lang.reflect.*;import org.json.*;
public final class GamesFeatureChecks extends Instrumentation {
  int checks;MainActivity activity;GamesClient client;
  public void onCreate(Bundle b){super.onCreate(b);start();}
  void check(boolean b,String s){if(!b)throw new AssertionError(s);checks++;}
  public void onStart(){Bundle result=new Bundle();try{
    Context context=getTargetContext();activity=(MainActivity)startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
    check(GamesData.IDS.length==7,"Seven games remain registered");
    JSONArray balls=new JSONArray("[{\"id\":0,\"x\":200,\"y\":200,\"pocketed\":false},{\"id\":1,\"x\":300,\"y\":200,\"pocketed\":false},{\"id\":2,\"x\":400,\"y\":200,\"pocketed\":false}]");
    double[] hit=GamesPoolVisual.hit(balls,200,200,1,0,0,2000);check(hit[2]==1&&Math.abs(hit[0]-278)<.001,"Guide stops at first contact, two radii from object center");
    double[] rail=GamesPoolVisual.hit(new JSONArray(),200,200,0,-1,0,2000);check(rail[1]==11&&rail[4]==1,"Guide clips to cushion");
    double[] mid=GamesPoolVisual.blend(new double[]{1,0,0,0},new double[]{-1,0,0,0},.5);check(mid[0]==1,"Rotation interpolation takes shortest arc");
    Bitmap a=Bitmap.createBitmap(100,100,Bitmap.Config.ARGB_8888),b=Bitmap.createBitmap(100,100,Bitmap.Config.ARGB_8888);Canvas ca=new Canvas(a),cb=new Canvas(b);ca.scale(3,3);cb.scale(3,3);Paint paint=new Paint(3);GamesPoolVisual.ball(ca,16,16,9,new double[]{1,0,0,0},paint);GamesPoolVisual.ball(cb,16,16,9,new double[]{.7071068,0,.7071068,0},paint);check(!a.sameAs(b),"Striped sphere visibly rotates rather than gliding");
    final GamesDrawingView[] drawing={null};final View[] pad={null};final JSONObject room=GamesData.obj("id","drawing-qa","seq",1,"game","drawing","status","playing","players",new JSONArray().put(GamesData.obj("actor","asnat")).put(GamesData.obj("actor","youssef")),"state",GamesData.obj("drawer",0,"turn",0,"phase","draw","winner",JSONObject.NULL,"word","rainbow","pattern","_______","round",1,"rounds",3,"points",new JSONArray().put(0).put(0),"strokes",new JSONArray(),"chat",new JSONArray(),"deadline",System.currentTimeMillis()+80000));
    runOnMainSync(()->{client=new GamesClient(new ApiClient(activity),"asnat",new GamesClient.Listener(){public void changed(){}public void reaction(String t){}});client.pending=null;client.connected=true;drawing[0]=new GamesDrawingView(activity,client);drawing[0].setBackgroundColor(Ui.BG);drawing[0].update(room);activity.setContentView(drawing[0]);});waitForIdleSync();Thread.sleep(500);
    runOnMainSync(()->{try{Field field=GamesDrawingView.class.getDeclaredField("pad");field.setAccessible(true);pad[0]=(View)field.get(drawing[0]);long now=SystemClock.uptimeMillis();for(int type:new int[]{MotionEvent.ACTION_DOWN,MotionEvent.ACTION_MOVE,MotionEvent.ACTION_UP}){MotionEvent e=MotionEvent.obtain(now,now+20*type,type,pad[0].getWidth()*.3f+type*30,pad[0].getHeight()*.4f,0);pad[0].onTouchEvent(e);e.recycle();}check(client.pending!=null&&"stroke".equals(client.pending.optJSONObject("action").optString("type")),"Drawing gesture enqueues a shared stroke");JSONArray points=client.pending.optJSONObject("action").optJSONArray("points");check(points.length()>=2,"Drawing stroke contains gesture points");for(int i=0;i<points.length();i++)for(int j=0;j<2;j++)check(points.optJSONArray(i).optDouble(j)>=0&&points.optJSONArray(i).optDouble(j)<=1,"Normalized point is inside canvas");
      JSONObject state=GamesData.state(room);state.put("strokes",new JSONArray("[{\"tool\":\"pen\",\"color\":\"#263451\",\"width\":0.02,\"points\":[[0.2,0.2],[0.8,0.2],[0.8,0.8],[0.2,0.8],[0.2,0.2]]},{\"tool\":\"fill\",\"color\":\"#cd8ca7\",\"width\":0.01,\"points\":[[0.5,0.5]]}]"));client.pending=null;drawing[0].update(room);Field image=pad[0].getClass().getDeclaredField("bitmap");image.setAccessible(true);Bitmap bitmap=(Bitmap)image.get(pad[0]);check(bitmap.getPixel(320,240)==Color.parseColor("#cd8ca7")&&bitmap.getPixel(20,20)==Color.WHITE,"Bucket fill stays within the enclosed boundary");}catch(Exception e){throw new RuntimeException(e);}});
    waitForIdleSync();Thread.sleep(700);screenshot("drawing-preview.png");
    runOnMainSync(()->{GamesBoard board=new GamesBoard(activity,"asnat",new GamesBoard.Host(){public void move(JSONObject j){}public void selection(){}public void aim(float v){}public void charge(float p,boolean r){}});JSONObject pool=GamesData.obj("id","pool-qa","game","pool","status","playing","players",GamesData.array(room,"players"),"state",GamesData.obj("turn",0,"winner",JSONObject.NULL,"balls",balls,"groups",new JSONArray().put(JSONObject.NULL).put(JSONObject.NULL)));board.setBackgroundColor(Ui.BG);board.update(pool,null,true);activity.setContentView(board);});waitForIdleSync();Thread.sleep(300);screenshot("pool-preview.png");
    client.close();new ApiClient(context).store.remove("games-pending:asnat");result.putString("stream","PASS: "+checks+" native pool and seventh-game checks.\n");finish(Activity.RESULT_OK,result);
  }catch(Throwable e){result.putString("stream","FAIL: "+e+"\n"+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
  void screenshot(String name)throws Exception{try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),name))){getUiAutomation().takeScreenshot().compress(Bitmap.CompressFormat.PNG,100,out);}}
}
